	function sendRequest(method, query, user, dataQuery) {
		return new Promise(function (resolve, reject) {
			var url = `https://${domain}/capi`;
			var xhr = new XMLHttpRequest();
			xhr.open(method, url);
			xhr.setRequestHeader("Content-Type", "application/json");
			xhr.onreadystatechange = function () {
				if (xhr.readyState === 4) {
					xhr.onerror = () => {
						console.error("ggerhrhyrt");
						return showError({
							desc: "Произошла ошибка на стороне сервера!",
							button: {
								back: false,
								backEvent: () => {},
								event: async () => {
									setActivity("home");
									setPopout(<ScreenSpinner size="medium" />);
									setLoading(1);
									await sendRequest("POST", "getUser", user).then((data) => {
										setUserData(data.userData);
										setLoad(false);
										setPopout(null);
										setLoading(0);
									});
								},
								text: "Попробовать снова",
							},
						});
					};
					xhr.onload = () => {
						resolve(JSON.parse(xhr.responseText));
					};
				}
			};
			var data = {
				data: dataQuery ? dataQuery : {},
				query,
				referer: window.location.search,
				uid: user.id,
			};
			xhr.send(JSON.stringify(data));
		});
	}
	function getTatals(data) {
		var res = 0;
		var res1 = 0;
		var res2 = 0;
		var res3 = "";
		var res33 = 0;
		data.bets.filter((x) => {
			if (x.user === fetchedUser.id) {
				res += x.defsum;
				if (x.win === 1) {
					res1 += x.sum;
				}
			}
		});
		res2 = res1 - res;
		res33 =
			res2 <= 0 ? `${res2}`.replace(/-/gi, "") : `${res2}`.replace(/-/gi, "");
		res3 = `${res2 < 0 ? "-" : res2 > 0 ? "+" : ""}`;
		setSumBets(res);
		setWinnerSum(res1);
		setTotalSum({
			str: res3,
			num: res33,
		});
	}
