	function getCoefs(bombs) {
		for (var a = 1, e = [], i = 0; i < 25 - bombs; i++) {
			a *= 1 - bombs / (25 - i);
			var r = Math.floor((0.9 / a) * 100) / 100;
			e.push(r);
		}
		return e;
	}
